// Generates `src/generated/app-versions.ts` — the versions of every package
// scaffolded by `okcms init`, captured from the workspace manifests at build
// time. The scaffold uses this map as the offline fallback when the npm
// registry cannot be reached; the preferred source at init time is the
// registry itself (`getLatestVersion`).
//
// Runs as part of `bun run build` (before tsc). The generated file is
// committed so tests can verify it stays in sync with the manifests.

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const pkgRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const repoRoot = join(pkgRoot, '..', '..');

/** Packages written into the scaffolded project's package.json. */
const TARGETS = {
  '@oktis-works/api': 'apps/api',
  '@oktis-works/admin': 'apps/admin',
  '@oktis-works/web': 'apps/web',
  '@oktis-works/worker': 'apps/worker',
  '@oktis-works/core': 'packages/core',
  '@oktis-works/plugin-runtime': 'packages/plugin-runtime',
  '@oktis-works/cms': 'packages/cli',
};

const versions = {};
for (const [name, dir] of Object.entries(TARGETS)) {
  const manifest = JSON.parse(readFileSync(join(repoRoot, dir, 'package.json'), 'utf-8'));
  if (!manifest.version || !/^\d+\.\d+\.\d+$/.test(manifest.version)) {
    console.error(`✗ ${dir}: version "${manifest.version}" is not semver`);
    process.exit(1);
  }
  versions[name] = manifest.version;
}

const outDir = join(pkgRoot, 'src', 'generated');
mkdirSync(outDir, { recursive: true });

const body = [
  '// GENERATED by scripts/generate-versions.mjs — do not edit by hand.',
  '// Versions captured from the workspace manifests at build time; regenerated',
  '// by `bun run build`. Used as the offline fallback for `okcms init` ranges',
  '// when the npm registry cannot be reached.',
  'export const APP_VERSIONS: Record<string, string> = {',
  ...Object.entries(versions).map(([name, version]) => `  '${name}': '${version}',`),
  '};',
  '',
].join('\n');

writeFileSync(join(outDir, 'app-versions.ts'), body, 'utf-8');
console.log(`✓ app-versions generated (${Object.keys(versions).length} packages)`);
